test('stores the invitation email in lowercase and matches existing users case-insensitively', () => {
  const store = storeWith(ann());
  const conflictResult = inviteUser(store, { body: { email: 'ANN@example.com', role: 'member' } });
  assert.equal(conflictResult.status, 409);

